import io
import streamlit as st
from PIL import Image
from google import genai

# ---------------- PAGE SETUP ----------------
st.set_page_config(page_title="Kisan AI", page_icon="🌱", layout="wide")

st.title("🌱 Kisan AI")
st.caption("A simple farming assistant for Pakistani farmers")
st.info(
    "This is a student/demo prototype. Crop matching uses simple sample rules, "
    "and AI advice is generated by Gemini when you provide an API key. "
    "Always confirm important farming decisions with a local agriculture officer."
)

# ---------------- AI CONNECTION ----------------
with st.sidebar:
    st.header("Settings")
    api_key = st.text_input(
        "Gemini API key (optional)",
        type="password",
        help="Get a key from Google AI Studio. Do not share it or upload it to GitHub."
    )
    st.caption("Without a key, the crop-matching demo still works.")

def ask_gemini(prompt, image=None):
    """Send a text prompt and optional image to Gemini."""
    if not api_key:
        raise ValueError("Add your Gemini API key in the sidebar first.")
    client = genai.Client(api_key=api_key)
    contents = [prompt]
    if image is not None:
        contents.append(image)
    response = client.models.generate_content(
        model="gemini-3.8-flash",
        contents=contents
    )
    return response.text or "I could not generate an answer. Please try again."

# ---------------- CROP MATCHING DEMO ----------------
# These are illustrative reference conditions, NOT a locally validated agronomy model.
# Replace them with a verified dataset and train/test a machine-learning model
# before using this for real farming decisions.
CROP_PROFILES = {
    "Wheat":       {"temp": 20, "rain": 75,  "ph": 6.5},
    "Rice":        {"temp": 27, "rain": 200, "ph": 6.0},
    "Maize":       {"temp": 24, "rain": 85,  "ph": 6.3},
    "Cotton":      {"temp": 28, "rain": 90,  "ph": 7.0},
    "Sugarcane":   {"temp": 28, "rain": 180, "ph": 6.5},
    "Chickpea":    {"temp": 22, "rain": 60,  "ph": 7.0},
    "Mustard":     {"temp": 18, "rain": 55,  "ph": 6.5},
    "Potato":      {"temp": 18, "rain": 90,  "ph": 5.8},
}

def crop_matches(temperature, rainfall, soil_ph):
    """Rank crops by distance from illustrative reference conditions."""
    scores = []
    for crop, profile in CROP_PROFILES.items():
        # Scale each measurement so rainfall does not dominate the score.
        distance = (
            abs(temperature - profile["temp"]) / 15
            + abs(rainfall - profile["rain"]) / 180
            + abs(soil_ph - profile["ph"]) / 3
        )
        scores.append((crop, distance))
    scores.sort(key=lambda item: item[1])
    return scores[:3]

tab1, tab2, tab3 = st.tabs(
    ["🌾 Crop suggestion", "🍃 Leaf photo checker", "💬 Ask Kisan AI"]
)

with tab1:
    st.subheader("Find crops to investigate for your field")
    st.write("Enter approximate field conditions. If you have a soil-test report, use its values.")
    c1, c2, c3 = st.columns(3)
    with c1:
        temperature = st.number_input("Average temperature (°C)", 0.0, 50.0, 25.0, 0.5)
    with c2:
        rainfall = st.number_input("Expected seasonal rainfall (mm)", 0.0, 1000.0, 100.0, 5.0)
    with c3:
        soil_ph = st.number_input("Soil pH", 3.0, 10.0, 6.5, 0.1)

    if st.button("Suggest crops", type="primary"):
        matches = crop_matches(temperature, rainfall, soil_ph)
        st.subheader("Top matches from the demo rules")
        for rank, (crop, distance) in enumerate(matches, start=1):
            st.write(f"**{rank}. {crop}** — demo match score: {1 / (1 + distance):.2f}")
        st.warning(
            "These are rough educational matches, not a guaranteed crop recommendation. "
            "The current demo does not use your location, irrigation, soil texture, "
            "seed variety, market price, or a laboratory soil analysis."
        )

with tab2:
    st.subheader("Ask about a crop leaf photo")
    st.write("Upload a clear photo showing the affected leaf. Include the whole leaf if possible.")
    uploaded_photo = st.file_uploader(
        "Choose a leaf photo",
        type=["jpg", "jpeg", "png"],
        key="leaf_photo"
    )
    if uploaded_photo:
        photo = Image.open(io.BytesIO(uploaded_photo.getvalue())).convert("RGB")
        st.image(photo, caption="Uploaded crop photo", use_container_width=True)
        if st.button("Analyze leaf photo", type="primary"):
            prompt = """
You are an agricultural information assistant helping a farmer in Pakistan.
Look at the uploaded plant image. Do not claim certainty from an image alone.
Explain:
1. What visible symptoms you notice.
2. Two or three possible causes (disease, pest, nutrient issue, or environmental stress).
3. What additional information a local agriculture expert would need.
4. Low-risk immediate steps the farmer can take.
5. When the farmer should contact an agriculture extension officer.
Do not prescribe a pesticide, exact dose, or chemical mixture. Ask the farmer to
follow local registered product labels and expert advice. If the image is unclear,
say so and request a clearer photo.
Use simple English. If possible, include a short Urdu explanation.
"""
            try:
                with st.spinner("Checking the photo..."):
                    answer = ask_gemini(prompt, photo)
                st.markdown(answer)
            except Exception as error:
                st.error(f"Could not analyze the photo: {error}")

with tab3:
    st.subheader("Ask a farming question")
    st.write("Example: How can I reduce water use when growing wheat?")
    if "messages" not in st.session_state:
        st.session_state.messages = []

    for message in st.session_state.messages:
        with st.chat_message(message["role"]):
            st.markdown(message["content"])

    question = st.chat_input("Write your farming question...")
    if question:
        st.session_state.messages.append({"role": "user", "content": question})
        with st.chat_message("user"):
            st.markdown(question)

        system_prompt = """
You are Kisan AI, a careful farming information assistant for farmers in Pakistan.
Give practical, simple, step-by-step advice. Ask for the crop, district, season,
irrigation method, and soil details when they are needed. Prefer safe, low-cost,
water-conscious practices. Do not invent local prices, weather, government schemes,
or pesticide approvals. Do not give exact pesticide doses or unsafe chemical mixes.
For serious crop disease, recommend confirmation from a local agriculture extension
officer or qualified agronomist. Make clear when advice is general rather than
specific to the farmer's field. Answer in the language the user uses.
"""
        try:
            with st.chat_message("assistant"):
                with st.spinner("Kisan AI is thinking..."):
                    answer = ask_gemini(system_prompt + "\nFarmer's question: " + question)
                st.markdown(answer)
            st.session_state.messages.append({"role": "assistant", "content": answer})
        except Exception as error:
            st.error(f"Could not get an AI answer: {error}")
            st.session_state.messages.pop()

st.divider()
st.caption("Kisan AI — beginner project prototype | Built with Python, Streamlit and Gemini")
